/**
 * Runs [param run] with a bridge port held by something else, handed to it to configure a server
 * with. A reserved port rather than 6505: holding the default here held it against the real server
 * of whichever project's editor was dialling it.
 */
async function withOccupiedBridgePort<T>(run: (port: number) => Promise<T>): Promise<T> {
  const port = await reservePort();
  const blocker = createServer();
  await new Promise<void>((resolve, reject) => {
    blocker.once('error', reject);
    blocker.listen(port, '127.0.0.1', () => {
      resolve();
    });
  });
  try {
    return await run(port);
  } finally {
    await new Promise<void>((resolve, reject) => {
      blocker.close((err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  }
}

/**
 * The slice of a ws WebSocket the bridge touches. The bridge's connection handler is private
 * and typed against the real class, so the fake is handed over through the seam below rather
 * than by pretending to be one.
 */
class FakeSocket extends EventEmitter {
  readonly name: string;
  readyState = 1;
  readonly sent: unknown[] = [];
  /** What the bridge closed it with, for a refusal whose code and reason are the answer. */
  closedWith: { code: number; reason: string } | null = null;

  constructor(name: string) {
    super();
    this.name = name;
  }

  send(payload: unknown): void {
    this.sent.push(payload);
  }

  close(code = 1000, reason = ''): void {
    // What ws does with a reason a close frame cannot carry. Without it this stand-in took any
    // reason, and the one naming two project paths that ended real servers passed here (#941).
    if (Buffer.byteLength(reason) > 123) {
      throw new RangeError('The message must not be greater than 123 bytes');
    }
    this.readyState = 3;
    this.closedWith = { code, reason };
    this.emit('close', code, Buffer.from(reason));
  }
}

function connectFake(bridge: ReturnType<typeof createBridge>, socket: FakeSocket): void {
  (bridge as unknown as { handleConnection: (socket: FakeSocket) => void }).handleConnection(socket);
}

/** The hello an editor sends once connected, which is where it says whose editor it is. */
function saysHello(socket: FakeSocket, projectPath: string): void {
  socket.emit('message', Buffer.from(JSON.stringify(greeting(projectPath))));
}

/**
 * Why a windowed engine may not run here, or null when it may. Only CI runs one: on a developer's
 * machine the window opens on their desktop and takes the foreground, and the owner ruled that
 * development never shows windows. `GDHARNESS_ALLOW_WINDOWS` opts a machine in.
 */
function windowedRunRefused(): string | null {
  if (!process.env['CI'] && !process.env['GDHARNESS_ALLOW_WINDOWS']) {
    return 'windowed runs are left to CI, so no window opens on a desktop; GDHARNESS_ALLOW_WINDOWS runs them here';
  }
  if (resolveHeadless(undefined, { platform: process.platform, variables: process.env })) {
    return 'no display for a windowed run';
  }
  return null;
}

function resolveGodotPath(): string | null {
  const candidate = process.env['GODOT_PATH'];
  return candidate && existsSync(candidate) ? candidate : null;
}

function testStaleDisconnectRegression(): void {
  const bridge = createBridge(0, 1000, '127.0.0.1');
  const first = new FakeSocket('first');
  const second = new FakeSocket('second');

  connectFake(bridge, first);
  saysHello(first, process.cwd());
  assert.equal(bridge.getStatus().connected, true, 'first socket should be connected');

  first.readyState = 3;
  connectFake(bridge, second);
  saysHello(second, process.cwd());
  assert.equal(bridge.getStatus().connected, true, 'second socket should be connected');

  first.emit('close', 1000, Buffer.from('late close from stale socket'));
  assert.equal(bridge.getStatus().connected, true, 'stale close must not disconnect the replacement socket');

  second.emit('close', 1000, Buffer.from('active socket closed'));
  assert.equal(bridge.getStatus().connected, false, 'active socket close should disconnect bridge');
}

/**
 * A connection nobody closed does not hold its process open. The bridge pings an open socket on a
 * timer, and a failing case that left one connected kept the regression run alive for two and a half
 * hours after it had printed its summary. A process holding a greeted fake editor ends on its own.
 */
async function testAnOpenConnectionDoesNotHoldItsProcess(): Promise<void> {
  const scratch = mkdtempSync(join(tmpdir(), 'gdharness-held-open-'));
  try {
    const script = join(scratch, 'held.ts');
    writeFileSync(
      script,
      [
        `import { EventEmitter } from 'node:events';`,
        `import { createBridge } from ${JSON.stringify(pathToFileURL(resolve('src', 'godot-bridge.ts')).href)};`,
        `import { greeting } from ${JSON.stringify(pathToFileURL(resolve('test', 'support', 'greeting.ts')).href)};`,
        `const socket = Object.assign(new EventEmitter(), { readyState: 1, send() {}, close() {}, terminate() {} });`,
        `const bridge = createBridge(0, 1000, '127.0.0.1');`,
        `(bridge as unknown as { handleConnection: (socket: unknown) => void }).handleConnection(socket);`,
        `socket.emit('message', Buffer.from(JSON.stringify(greeting(process.cwd()))));`,
        `console.log('connected', bridge.isConnected());`,
      ].join('\n'),
    );
    const child = spawnHidden(process.execPath, [script], { stdio: ['ignore', 'pipe', 'pipe'] });
    let printed = '';
    child.stdout.on('data', (chunk: Buffer) => {
      printed += chunk.toString();
    });
    child.stderr.on('data', (chunk: Buffer) => {
      printed += chunk.toString();
    });
    const ended = await Promise.race([exitOf(child), delay(15_000).then(() => null)]);
    if (ended === null) {
      child.kill();
    }
    assert.match(
      printed,
      /connected true/,
      `the fake editor should be connected, or this proves nothing: ${printed}`,
    );
    assert.deepEqual(ended, { code: 0, signal: null }, `and the process should end on its own: ${printed}`);
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
}

/**
 * A server that knows its project serves that project's editor and turns away every other one.
 *
 * The addon falls back to the default port whenever its own project holds no announcement, which
 * is every project whose server has not run yet, so any server on that port took the connection
 * and served it. Tool calls reached an editor showing another project's scenes and both sides
 * called the bridge healthy. The addon has always said which project it has open; nothing read it.
 */
function testOneServerOneProjectRegression(): void {
  // Short enough that a reason naming both fits a close frame. Under the temporary directory the
  // pair came to 168 bytes, a reason no close frame carries, which the stand-in accepted until it
  // was made to refuse what ws refuses (#941); the long pair is checked below.
  const mine = resolve('/gdharness-one-server-mine');
  const theirs = resolve('/gdharness-one-server-theirs');

  const bridge = createBridge(0, 1000, '127.0.0.1', mine);
  const stranger = new FakeSocket('stranger');
  connectFake(bridge, stranger);
  saysHello(stranger, theirs);

  assert.equal(bridge.getStatus().connected, false, "another project's editor is not served");
  const turnedAway = stranger.closedWith;
  assert.ok(turnedAway, 'and is closed rather than left half connected');
  assert.equal(turnedAway.code, 4001, 'with its own close code, which the addon reads');
  assert.match(
    turnedAway.reason,
    /this server serves .*and that editor has .* open/,
    'and a reason naming both projects, since neither side can see the other',
  );

  // #941: paths long enough that naming both overruns a close frame. ws threw, uncaught, and the
  // server ended; the refusal is still made, with a reason that fits and ends with this project.
  const longMine = join(tmpdir(), `gdharness-one-server-${'mine'.repeat(30)}`);
  const long = createBridge(0, 1000, '127.0.0.1', longMine);
  const farAway = new FakeSocket('far away');
  connectFake(long, farAway);
  saysHello(farAway, join(tmpdir(), `gdharness-one-server-${'theirs'.repeat(20)}`));
  assert.equal(farAway.closedWith?.code, 4001, 'a long pair of paths is still turned away');
  const reason = farAway.closedWith.reason;
  assert.ok(Buffer.byteLength(reason) <= 123, `in a reason a close frame carries: ${reason}`);
  assert.match(
    reason,
    new RegExp(`^\\.\\.\\..*${'mine'.repeat(10)}$`),
    'cut from the front, so the folder is kept',
  );
  assert.equal(closeReason('short enough', 'start'), 'short enough', 'and a short reason goes as it is');
  // A character outside the basic plane is four bytes and two UTF-16 units, and is never split.
  const astral = closeReason('\u{1F3B2}'.repeat(40), 'start');
  assert.ok(Buffer.byteLength(astral) <= 123 && !astral.includes('�'), astral);
  assert.equal(astral, `${'\u{1F3B2}'.repeat(30)}...`);

  // The same project as Godot spells it: forward slashes and a trailing one, against a config
  // holding a Windows path. A comparison that failed this would refuse the editor it exists for.
  const own = new FakeSocket('own');
  connectFake(bridge, own);
  saysHello(own, `${mine.replaceAll('\\', '/')}/`);
  assert.equal(bridge.getStatus().connected, true, "its own project's editor is served");
  assert.equal(own.closedWith, null, 'and is not closed on the way');

  // A project inside another project is a different project, so containment is not the question.
  const nested = createBridge(0, 1000, '127.0.0.1', mine);
  const inside = new FakeSocket('inside');
  connectFake(nested, inside);
  saysHello(inside, join(mine, 'demo'));
  assert.equal(nested.getStatus().connected, false, 'a project under this one is still another one');

  // Nothing said which project, which is every hand-written config: the port stays the contract.
  const anywhere = createBridge(0, 1000, '127.0.0.1');
  const guest = new FakeSocket('guest');
  connectFake(anywhere, guest);
  saysHello(guest, theirs);
  assert.equal(anywhere.getStatus().connected, true, 'a server with no project takes whoever comes');

  // Every socket the bridge took is holding a keepalive timer, and a timer nobody stopped keeps
  // the whole run from ever ending. Only the two that were served: a refused one was closed by
  // the bridge as it turned it away, which is the thing being checked above.
  own.close();
  guest.close();
}

/**
 * A process that greets without a server's mark is looked up before it is taken as the editor, and
 * one whose command line makes it one job that quits is turned away (#834).
 *
 * A gate's `godot --headless --import` loaded the editor addon and was served as the editor, so a
 * start for another project was refused while it ran, and the project's real editor, dialling in
 * meanwhile, was the one turned away as a second connection. The reader is handed in, so each of
 * its answers, and the wait for one, can be put to the bridge on purpose.
 */
async function testAOneShotEngineRunIsTurnedAwayAtTheBridge(): Promise<void> {
  const mine = join(tmpdir(), 'gdharness-one-shot-bridge');
  const hello = (socket: FakeSocket, pid: number, opened = false): void => {
    socket.emit(
      'message',
      Buffer.from(JSON.stringify(greeting(mine, { editor_pid: pid, opened_by_a_server: opened }))),
    );
  };
  const answers = new Map<number, string | null | undefined | Error>([
    [101, '--import'],
    [102, null],
    [103, new Error('the listing was refused')],
  ]);
  const asked: number[] = [];
  let release: ((option: string | null) => void) | null = null;
  const bridge = createBridge(0, 1000, '127.0.0.1', mine);
  bridge.identifyEditorsWith(async (pid) => {
    asked.push(pid);
    if (pid === 104) {
      return await new Promise<string | null>((done) => {
        release = done;
      });
    }
    const answer = answers.get(pid);
    if (answer instanceof Error) {
      throw answer;
    }
    return answer;
  });
  const settled = (): Promise<void> => delay(20);
  // Every socket the bridge takes holds a keepalive timer, and one left open by a failing assertion
  // kept the whole run from ending, so each is closed however the case ends.
  const opened: FakeSocket[] = [];
  const socket = (name: string): FakeSocket => {
    const made = new FakeSocket(name);
    opened.push(made);
    return made;
  };
  try {
    await turnedAwayAtTheBridge(bridge, socket, hello, settled, asked, () => release);
  } finally {
    for (const made of opened) {
      if (made.readyState !== 3) {
        made.close();
      }
    }
  }
}

/**
 * A one-shot run of another project is turned away as a one-shot, quietly. A gate's `--import` of a
 * fresh worktree has no announcement and dials the shared default port; closed as another
 * project's editor, the addon warns and gates refuse a push on the warning, while closed as a
 * one-shot it stops dialling and says nothing. An editor of another project is still told whose
 * server this is, after its command line is read, and one that sends no pid is told at once.
 */
async function testAOneShotRunOfAnotherProjectIsTurnedAwayQuietly(): Promise<void> {
  const mine = resolve('/gdharness-one-shot-mine');
  const worktree = resolve('/gdharness-one-shot-worktree');
  const bridge = createBridge(0, 1000, '127.0.0.1', mine);
  bridge.identifyEditorsWith((pid) => Promise.resolve(pid === 201 ? '--import' : null));
  const hello = (socket: FakeSocket, pid: number | undefined): void => {
    socket.emit('message', Buffer.from(JSON.stringify(greeting(worktree, { editor_pid: pid }))));
  };
  const opened: FakeSocket[] = [];
  const socket = (name: string): FakeSocket => {
    const made = new FakeSocket(name);
    opened.push(made);
    connectFake(bridge, made);
    return made;
  };
  try {
    const importing = socket('import of a worktree');
    hello(importing, 201);
    await delay(20);
    assert.equal(
      importing.closedWith?.code,
      4002,
      `closed as a one-shot: ${JSON.stringify(importing.closedWith)}`,
    );
    assert.match(importing.closedWith.reason, /pid 201 was started with --import/);
    assert.equal(bridge.getStatus().turnedAway?.pid, 201, 'and status names it');

    const editor = socket('editor of another project');
    hello(editor, 202);
    await delay(20);
    assert.equal(
      editor.closedWith?.code,
      4001,
      `an editor of another project is told so: ${JSON.stringify(editor.closedWith)}`,
    );
    assert.match(editor.closedWith.reason, /^this server serves /);

    const unsaid = socket('an addon that sends no pid');
    hello(unsaid, undefined);
    assert.equal(unsaid.closedWith?.code, 4001, 'and one with no pid to read is told at once');
  } finally {
    for (const made of opened) {
      if (made.readyState !== 3) {
        made.close();
      }
    }
  }
}

/**
 * A test run's engine entries are folded and its script errors are known apart from other errors.
 *
 * A recursion without end printed one `Stack underflow` entry per frame it unwound, two hundred
 * identical entries in one answer, before the `Stack overflow` that explained them. And the verdict
 * rests on which headline an error carried: `push_error` and the engine's own checks both print
 * `ERROR`, and only `SCRIPT ERROR` says the code under test faulted.
 */
function testEngineEntriesFoldAndScriptErrorsAreKnown(): void {
  const log = new GameLog();
  log.append(
    'transcript',
    [
      'SCRIPT ERROR: Stack overflow. Check for infinite recursion in your script.',
      '   at: depth (res://tests/overflow_test.gd:5)',
      ...Array.from({ length: 4 }, () =>
        [
          'ERROR: Stack underflow! (Engine Bug)',
          '   at: exit_function (modules/gdscript/gdscript.h:529)',
        ].join('\n'),
      ),
      'ERROR: Stack underflow! (Engine Bug)',
      '   at: exit_function (modules/gdscript/gdscript.h:530)',
      'ERROR: an error the case means to print',
      '   at: push_error (core/variant/variant_utility.cpp:1023)',
      'USER ERROR: an error from an older engine',
      'WARNING: a warning',
      'SCRIPT ERROR: Stack overflow. Check for infinite recursion in your script.',
      '   at: depth (res://tests/overflow_test.gd:5)',
      '',
    ].join('\n'),
  );
  log.finish();

  const byScript = log.all.filter((entry) => log.raisedByScript(entry)).map((entry) => entry.index);
  assert.deepEqual(byScript, [0, 9], 'the two SCRIPT ERROR entries and nothing else');

  const folded = foldedRepeats(log.all);
  assert.deepEqual(
    folded.map((entry) => [entry.index, entry.text, entry.times]),
    [
      [0, 'Stack overflow. Check for infinite recursion in your script.', 2],
      [1, 'Stack underflow! (Engine Bug)', 4],
      [5, 'Stack underflow! (Engine Bug)', undefined],
      [6, 'an error the case means to print', undefined],
      [7, 'an error from an older engine', undefined],
      [8, 'a warning', undefined],
    ],
    `one entry per distinct one, at its first index, counted when repeated: ${JSON.stringify(folded)}`,
  );
  assert.deepEqual(folded[1]?.detail, ['at: exit_function (modules/gdscript/gdscript.h:529)']);
  assert.equal('detail' in (folded[5] ?? {}), false, 'an entry with no detail carries none');
  assert.equal(log.count('error'), 9, 'the count is of every entry, folded or not');

  // A backtrace of one frame per call down to the limit is written once per run of identical frames.
  const deep = new GameLog();
  deep.append(
    'transcript',
    [
      'SCRIPT ERROR: Stack overflow. Check for infinite recursion in your script.',
      '   at: depth (res://overflow_test.gd:4)',
      '   GDScript backtrace (most recent call first):',
      ...Array.from({ length: 1014 }, (_, frame) => `       [${frame}] depth (res://overflow_test.gd:5)`),
      '       [1014] test_runs_away (res://overflow_test.gd:9)',
      '       [1015] test_runs_away (res://overflow_test.gd:9)',
      '       [1016] depth (res://overflow_test.gd:5)',
      '',
    ].join('\n'),
  );
  deep.finish();
  assert.deepEqual(forAnswer(deep.all)[0]?.detail, [
    'at: depth (res://overflow_test.gd:4)',
    'GDScript backtrace (most recent call first):',
    '[0-1013] depth (res://overflow_test.gd:5)',
    '[1014-1015] test_runs_away (res://overflow_test.gd:9)',
    '[1016] depth (res://overflow_test.gd:5)',
  ]);

  // Functions calling one another repeat a cycle of frames: the shape of game-b's overflow, an
  // eight-function cycle after the frames it started from, ending part-way round, then its caller.
  const cycle = [
    'count_at',
    '_fired',
    'strength_of',
    'gear',
    'strength',
    '_worn_strength',
    'loadout',
    'coin_held',
  ];
  const mutual = new GameLog();
  mutual.append(
    'transcript',
    [
      'SCRIPT ERROR: Stack overflow. Check for infinite recursion in your script.',
      '   GDScript backtrace (most recent call first):',
      '       [0] deepest (res://core/a.gd:1)',
      ...Array.from(
        { length: 8 * 125 + 3 },
        (_, at) => `       [${at + 1}] ${cycle[at % 8] ?? ''} (res://core/x.gd:${at % 8})`,
      ),
      '       [1004] test_lends (res://tests/heriot_test.gd:30)',
      '',
    ].join('\n'),
  );
  mutual.finish();
  assert.deepEqual(forAnswer(mutual.all)[0]?.detail, [
    'GDScript backtrace (most recent call first):',
    '[0] deepest (res://core/a.gd:1)',
    '[1-1000] these 8 frames, 125 times over:',
    ...cycle.map((name, at) => `  ${name} (res://core/x.gd:${at})`),
    '[1001] count_at (res://core/x.gd:0)',
    '[1002] _fired (res://core/x.gd:1)',
    '[1003] strength_of (res://core/x.gd:2)',
    '[1004] test_lends (res://tests/heriot_test.gd:30)',
  ]);
  // A cycle holding one frame twice in a row is the cycle, not that frame twice and the rest apart.
  const doubled = new GameLog();
  doubled.append(
    'transcript',
    [
      'SCRIPT ERROR: Stack overflow. Check for infinite recursion in your script.',
      ...Array.from(
        { length: 30 },
        (_, at) => `   [${at}] ${['x (a:1)', 'x (a:1)', 'y (a:2)'][at % 3] ?? ''}`,
      ),
      '',
    ].join('\n'),
  );
  doubled.finish();
  assert.deepEqual(forAnswer(doubled.all)[0]?.detail, [
    '[0-29] these 3 frames, 10 times over:',
    '  x (a:1)',
    '  x (a:1)',
    '  y (a:2)',
  ]);

  // The engine writes a headline and its detail down one pipe. gdUnit4 indents its progress lines on
  // stdout, and one landing after an error on stderr is a line of its own, not that error's detail.
  const piped = new GameLog();
  piped.append('stderr', 'ERROR: Stack underflow! (Engine Bug)\n');
  piped.append('stdout', '  res://tests/overflow_test.gd > test_runs_away PASSED 87ms\n');
  piped.append('stderr', '   at: exit_function (modules/gdscript/gdscript.h:529)\n');
  piped.finish();
  assert.deepEqual(
    piped.all.map((entry) => [entry.source, entry.severity, entry.text, entry.detail]),
    [
      [
        'stderr',
        'error',
        'Stack underflow! (Engine Bug)',
        ['at: exit_function (modules/gdscript/gdscript.h:529)'],
      ],
      ['stdout', 'info', '  res://tests/overflow_test.gd > test_runs_away PASSED 87ms', []],
    ],
    JSON.stringify(piped.all),
  );

  // An error message of several lines, as Godot's exporter prints it: the lines after the headline
  // are unindented, and only the `at:` line ends the message. A message not ending in a colon takes
  // no line after it, a line after the `at:` is the run's own, and stdout never continues a message.
  const multiline = new GameLog();
  for (const said of [
    'ERROR: Cannot export project with preset "Penguin" due to configuration errors:',
    'No export template found at the expected path:',
    'C:/templates/4.7.2.stable/linux_debug.x86_64',
    '',
    '   at: _fs_changed (editor/editor_node.cpp:1401)',
    'a print after it',
    'ERROR: Project export for preset "Penguin" failed.',
    'a print after a message that announced nothing more',
  ]) {
    multiline.append('stderr', `${said}\n`);
  }
  multiline.append('stdout', 'WARNING: printed by the game:\n');
  multiline.append('stdout', 'the game goes on\n');
  multiline.finish();
  assert.deepEqual(
    multiline.all.map((entry) => [entry.source, entry.severity, entry.text, entry.detail]),
    [
      [
        'stderr',
        'error',
        'Cannot export project with preset "Penguin" due to configuration errors:',
        [
          'No export template found at the expected path:',
          'C:/templates/4.7.2.stable/linux_debug.x86_64',
          'at: _fs_changed (editor/editor_node.cpp:1401)',
        ],
      ],
      ['stderr', 'info', 'a print after it', []],
      ['stderr', 'error', 'Project export for preset "Penguin" failed.', []],
      ['stderr', 'info', 'a print after a message that announced nothing more', []],
      ['stdout', 'warning', 'printed by the game:', []],
      ['stdout', 'info', 'the game goes on', []],
    ],
    JSON.stringify(multiline.all),
  );

  // Every answer listing a run's entries folds them before its limit, so the limit and the count of
  // what it left out are of distinct entries: a per-frame warning does not push the rest out. Warnings
  // rather than errors, so the export below is judged exported and answers with its entries.
  const busy = new GameLog();
  busy.append(
    'transcript',
    [
      'WARNING: the first thing printed',
      'WARNING: the second thing printed',
      ...Array.from({ length: 300 }, () => 'WARNING: a per-frame warning'),
      'WARNING: the last thing printed',
      '',
    ].join('\n'),
  );
  busy.finish();
  const newest = busy.selectFolded({ severity: 'warning', sinceLastCall: false, limit: 3 });
  assert.deepEqual(
    newest.entries.map((entry) => [entry.text, entry.times]),
    [
      ['the second thing printed', undefined],
      ['a per-frame warning', 300],
      ['the last thing printed', undefined],
    ],
    JSON.stringify(newest),
  );
  assert.equal(newest.omitted, 1, 'one distinct entry left out, not three hundred');
  const exported = parseTextContent({
    result: exportAnswer(
      { log: busy, exitCode: 0, exitSignal: null, failure: null },
      { preset: 'Linux', outputPath: 'builds/game.x86_64', debug: false },
      null,
      5,
    ),
  });
  assert.deepEqual(
    asArray(get(exported, 'entries')).map((entry) => [get(entry, 'text'), get(entry, 'times')]),
    [
      ['the first thing printed', undefined],
      ['the second thing printed', undefined],
      ['a per-frame warning', 300],
      ['the last thing printed', undefined],
    ],
    `an export's answer folds them too: ${JSON.stringify(exported)}`,
  );
  assert.equal(get(exported, 'warnings'), 303, 'and counts every one');
}

/**
 * The profiler's reading of the engine's wire format, its sums and its answer, without an engine.
 *
 * The bytes are built here as `core/io/marshalls.cpp` writes them at 4.7.2, in the shapes the engine
 * actually uses, which are not the ones this server writes: names as StringName (21) rather than
 * String, floats as 32-bit where that loses nothing, an int past 32 bits with its flag, and a packed
 * string array whose lengths count a trailing NUL. The answer is rendered in every state it has, so
 * a sentence only one state reaches is read before somebody is handed it.
 */
function testTheProfilerReadsWhatTheEngineSends(): void {
  const bytes: number[] = [];
  const u32 = (value: number): void => {
    bytes.push(value & 0xff, (value >>> 8) & 0xff, (value >>> 16) & 0xff, (value >>> 24) & 0xff);
  };
  const text = (value: string, nul = false): void => {
    const encoded = [...new TextEncoder().encode(value), ...(nul ? [0] : [])];
    u32(encoded.length);
    bytes.push(...encoded, ...Array.from({ length: (4 - (encoded.length % 4)) % 4 }, () => 0));
  };
  u32(28);
  u32(6);
  u32(21);
  text('res://a.gd::3::f');
  u32(2 | (1 << 16));
  const wide = new DataView(new ArrayBuffer(8));
  wide.setBigInt64(0, 2n ** 40n, true);
  bytes.push(...new Uint8Array(wide.buffer));
  u32(3);
  const narrow = new DataView(new ArrayBuffer(4));
  narrow.setFloat32(0, 0.5, true);
  bytes.push(...new Uint8Array(narrow.buffer));
  u32(34);
  u32(2);
  text('x', true);
  text('yz', true);
  u32(27);
  u32(1);
  u32(2);
  u32(1);
  u32(1);
  u32(1);
  u32(5);
  narrow.setFloat32(0, 1, true);
  bytes.push(...new Uint8Array(narrow.buffer));
  narrow.setFloat32(0, 2, true);
  bytes.push(...new Uint8Array(narrow.buffer));
  assert.deepEqual(decodeVariant(Uint8Array.from(bytes)), [
    'res://a.gd::3::f',
    2 ** 40,
    0.5,
    ['x', 'yz'],
    { kind: 'dictionary', entries: [[1, true]] },
    { kind: 'Vector2', values: [1, 2] },
  ]);

  // The command decodes back to what the game checks: a String name, thread 1, then the data.
  const command = profilerOn(1536);
  assert.equal(
    new DataView(command.buffer).getUint32(0, true),
    command.length - 4,
    'its length, little-endian',
  );
  assert.deepEqual(decodeVariant(command.subarray(4)), ['profiler:servers', 1, [true, [1536, false]]]);

  // The most functions a frame may carry, kept below the game's debugger queue, which drops the
  // messages naming functions past its size: the engine's default queue, and a project's own.
  assert.deepEqual(
    [
      queuedMessagesOf(null),
      queuedMessagesOf('config_version=5\n\n[network]\n\nlimits/debugger/max_queued_messages=4096\n'),
      queuedMessagesOf('config_version=5\n\n[network]\n\nlimits/debugger/max_queued_messages=0\n'),
      queuedMessagesOf('config_version=5\n\n[application]\n\nlimits/debugger/max_queued_messages=4096\n'),
    ],
    [2048, 4096, 2048, 2048],
    "the project's queue when it sets one in [network], the engine's default otherwise",
  );
  assert.deepEqual(
    [frameFunctionsFor(2048), frameFunctionsFor(4096), frameFunctionsFor(100)],
    [1536, 3584, 64],
  );

  // Messages however the reads cut them, and one this reader cannot take skipped on its own.
  const unknownType = Uint8Array.of(12, 0, 0, 0, 28, 0, 0, 0, 1, 0, 0, 0, 99, 0, 0, 0, 0, 0, 0, 0);
  const joined = Uint8Array.from([
    ...framedCommand('first', [1]),
    ...unknownType.subarray(0, 16),
    ...framedCommand('second', ['two']),
  ]);
  new DataView(joined.buffer).setUint32(framedCommand('first', [1]).length, 12, true);
  const stream = new DebuggerStream();
  const read = [...joined].flatMap((byte) => stream.push(Uint8Array.of(byte)));
  assert.deepEqual(
    read.map((one) => ('message' in one ? [one.message, one.data] : 'unreadable')),
    [['first', [1]], 'unreadable', ['second', ['two']]],
    JSON.stringify(read),
  );

  // Frames summed per function past the servers' section, and the engine's totals replacing them.
  const aggregate = new ProfileAggregate(1000, 3);
  const take = (message: string, data: unknown[]): void => {
    aggregate.take({ message, thread: 1, data: data as never }, 2000);
  };
  take('servers:function_signature', ['res://w.gd::6::Work.square', 0]);
  take('servers:function_signature', ['res://w.gd::10::Work.busy', 1]);
  const frame = (calls: number, numbered = 7): unknown[] => [
    numbered,
    0.016,
    0.01,
    0,
    0.016,
    0.004,
    1,
    'physics_2d',
    4,
    'step',
    0.001,
    'flush',
    0.0,
    10,
    0,
    calls,
    0.002,
    0.002,
    0,
    1,
    1,
    0.001,
    0.003,
    0,
  ];
  take('servers:profile_frame', frame(100));
  take('servers:profile_frame', frame(50, 9));
  take('servers:profile_frame', [1, 2, 3]);
  const summed = aggregate.snapshot();
  assert.deepEqual(
    [
      summed.frames,
      summed.complete,
      summed.unreadable,
      summed.functions['res://w.gd::6::Work.square']?.calls,
    ],
    [2, false, 1, 150],
    JSON.stringify(summed),
  );
  // The game's own numbers for the frames read, which the unreadable one does not move.
  assert.deepEqual([summed.firstFrame, summed.lastFrame], [7, 9], JSON.stringify(summed));
  take('servers:profile_total', [9, 0, 0, 0, 0, 0, 0, 5, 0, 200, 0.5, 0.5, 0]);
  const whole = aggregate.snapshot();
  assert.deepEqual(
    [whole.complete, Object.keys(whole.functions), whole.functions['res://w.gd::6::Work.square']?.calls],
    [true, ['res://w.gd::6::Work.square'], 200],
    'the total is what the frames add up to, so it replaces them',
  );
  assert.deepEqual(
    [summed.cappedFrames, whole.totalCapped],
    [0, false],
    'two functions a frame is under three',
  );

  // A frame carrying as many as were asked for is counted, since the engine left out the rest; and a
  // function whose naming message never came is kept under its number.
  const tight = new ProfileAggregate(1000, 2);
  const into = (message: string, data: unknown[]): void => {
    tight.take({ message, thread: 1, data: data as never }, 2000);
  };
  into('servers:function_signature', ['res://w.gd::6::Work.square', 0]);
  into('servers:profile_frame', frame(1));
  into('servers:profile_frame', [...frame(1).slice(0, 13), 5, 0, 1, 0.002, 0.002, 0]);
  const tightFrames = tight.snapshot();
  assert.deepEqual(
    [tightFrames.cappedFrames, tightFrames.frameFunctions, Object.keys(tightFrames.functions).sort()],
    [1, 2, ['#1', 'res://w.gd::6::Work.square']],
    'one of the two frames at the cap, and the function never named kept as #1',
  );
  into('servers:profile_total', [9, 0, 0, 0, 0, 0, 0, 10, 0, 2, 0.5, 0.5, 0, 1, 1, 0.1, 0.1, 0]);
  assert.equal(tight.snapshot().totalCapped, true, 'and totals at the cap are said to be');

  // What the game's debugger queue dropped, as the engine reports it once the queue has room: an
  // error message whose fields are the engine's OutputError, the count in its description. Another
  // error the game reported is not a drop.
  const overflow = (count: number): unknown[] => [
    0,
    0,
    1,
    20,
    '',
    '',
    0,
    'TOO_MANY_MESSAGES',
    `Too many messages! ${count} messages were dropped. Profiling might misbheave, try raising 'network/limits/debugger/max_queued_messages' in project setting.`,
    false,
    0,
  ];
  const lossy = new ProfileAggregate(1000, 2);
  assert.equal(lossy.snapshot().dropped, undefined, 'nothing dropped is left out');
  lossy.take({ message: 'error', thread: 1, data: overflow(12) as never }, 2000);
  lossy.take(
    { message: 'error', thread: 1, data: [0, 0, 1, 20, 'res://w.gd', 'f', 3, 'oops', '', false, 0] as never },
    2000,
  );
  lossy.take({ message: 'error', thread: 1, data: overflow(3) as never }, 2000);
  assert.equal(lossy.snapshot().dropped, 15, JSON.stringify(lossy.snapshot()));

  assert.deepEqual(signatureParts('res://w.gd::10::Work.busy'), {
    script: 'res://w.gd',
    line: 10,
    function: 'Work.busy',
  });
  assert.deepEqual(signatureParts('res://s.tscn::GDScript_ab::7::f(lambda)'), {
    script: 'res://s.tscn::GDScript_ab',
    line: 7,
    function: 'f(lambda)',
  });

  const totals = (functions: ProfileTotals['functions']): ProfileTotals => ({
    startedAt: 0,
    lastFrameAt: 10,
    frames: 3,
    complete: true,
    unreadable: 0,
    functions,
  });
  const table = profiledFunctions(
    totals({
      'res://a.gd::1::slow': { calls: 1, selfSeconds: 0.5, totalSeconds: 0.9 },
      'res://a.gd::2::fast': { calls: 9, selfSeconds: 0.1, totalSeconds: 0.1 },
      'res://a.gd::3::inside': { calls: 0, selfSeconds: 99, totalSeconds: 99 },
      'res://a.gd::4::mid': { calls: 2, selfSeconds: 0.3, totalSeconds: 0.4 },
    }),
    2,
  );
  assert.deepEqual(
    [table.functions.map((one) => one.function), table.omitted, table.counted, table.scriptMs],
    [['slow', 'mid'], 1, 3, 900],
    'by self time; the function the profiler started inside is not counted, nor its time',
  );

  assert.deepEqual(withEngineArguments(['--path', 'p', '--', '--level=2'], ['--remote-debug', 'x']), [
    '--path',
    'p',
    '--remote-debug',
    'x',
    '--',
    '--level=2',
  ]);
  assert.deepEqual(withEngineArguments(['--path', 'p'], ['--x']), ['--path', 'p', '--x']);

  const answer = (reading: Partial<Parameters<typeof profileAnswer>[0]>): Record<string, unknown> =>
    profileAnswer(
      { through: 'gdharness', running: false, totals: null, coveredMs: 0, runtimeAddon: true, ...reading },
      30,
    );
  const say = (reading: Partial<Parameters<typeof profileAnswer>[0]>): string =>
    String(answer(reading)['note']);
  assert.match(say({ running: true }), /^The game has not connected to the profiler yet/);
  assert.match(say({}), /^The game never connected to the profiler, so nothing was measured/);
  assert.equal(
    answer({ totals: totals({}) })['note'],
    undefined,
    'the engine’s own totals need nothing said',
  );
  // Where the frames begin and whether any between them went missing, from the game's own numbers.
  // A run without the runtime addon on a loaded runner summed 12 of its scene's 30 frames, and
  // nothing in the answer said which 12.
  const numbered = (firstFrame: number, lastFrame: number, frames: number, runtimeAddon = false): string =>
    say({ runtimeAddon, totals: { ...totals({}), complete: false, firstFrame, lastFrame, frames } });
  assert.match(
    numbered(18, 29, 12),
    / The profiler came on at the game's frame 18, so its first 18 frames are not in these, the main scene's _ready among them: without the runtime addon nothing holds the game's start until the profiler is on\./,
  );
  assert.match(
    numbered(1, 29, 29, true),
    / The profiler came on at the game's frame 1, so its first frame is not in these, the main scene's _ready among them\.(?: |$)/,
  );
  assert.match(
    numbered(0, 29, 27),
    / 3 of the game's frames between the first and the last that arrived did not arrive, so their script time is not in these\./,
  );
  assert.match(numbered(0, 29, 29), / One of the game's frames between the first and the last/);
  assert.doesNotMatch(
    numbered(0, 29, 30),
    /came on at the game's frame|did not arrive/,
    'all 30 from the start',
  );
  assert.match(
    numbered(0, 29, 30),
    /^These are the 30 frames that arrived, summed/,
    'which still says what it is',
  );
  // Totals with the game still going: something switched the profiler off early, and what can have
  // depends on who is the game's debugger.
  assert.match(
    say({ running: true, totals: totals({}) }),
    /^The engine's totals arrived while the game is still running, which it sends only when the profiler is switched off, so the game itself, through EngineDebugger, switched it off before the game ended\. They cover the run up to then and nothing after\.$/,
  );
  assert.match(
    say({ running: true, totals: totals({}), through: 'editor' }),
    /so the editor's Profiler tab or the game itself, through EngineDebugger, switched it off/,
  );
  const partial = { ...totals({}), complete: false };
  assert.match(
    say({ running: true, totals: partial }),
    /^The run is still going, so these are the 3 frames summed so far, written at most half a second behind\.$/,
  );
  assert.match(say({ running: true, totals: partial, through: 'editor' }), /summed so far\.$/);
  assert.match(say({ totals: { ...partial, frames: 1 } }), /^These are the one frame that arrived, summed/);
  // An ended run without totals: why they did not come, and what that leaves out, which is told
  // apart from data lost because it can be nothing at all.
  assert.match(
    say({ totals: partial }),
    /^These are the 3 frames that arrived, summed, without the engine's own totals, which it sends only when the profiler is switched off\. The runtime addon switches the profiler off as the game quits, and did not here: either it was no longer running in this game by then, which a project can arrange for some scenes; or the game ended without taking its tree down, as a crash or a kill does; or the totals did not reach the debugger before the game exited, which the game then says in its output\. Not in them is any script time after the last frame sent: a frame still queued as the game exited, .* and what scripts did as it quit, such as in _exit_tree\. That can be nothing: a scene that does its work in _ready and quits has all of it in its first frame\.$/,
  );
  assert.doesNotMatch(
    say({ totals: partial }),
    /setup installs it|no gdharness runtime addon/,
    'a project with the addon is not told to install it',
  );
  // The engine said its queue dropped messages, which is then the reason rather than three guesses.
  for (const [dropped, said] of [
    [1, 'one message'],
    [40, '40 messages'],
  ] as const) {
    assert.match(
      say({ totals: { ...partial, dropped } }),
      new RegExp(
        `^These are the 3 frames that arrived, summed, without the engine's own totals, which it sends only when the profiler is switched off\\. The game's debugger queue dropped ${said}, the engine reported, and those can be a frame or the totals: the queue holds as many as the project's network/limits/debugger/max_queued_messages, and raising it makes room\\. Not in them is any script time`,
      ),
    );
  }
  assert.doesNotMatch(say({ totals: { ...partial, dropped: 2 } }), /did not here/);
  assert.match(
    say({ totals: partial, runtimeAddon: false }),
    /switched off\. This project has no gdharness runtime addon, .*: setup installs it\. Not in them is any script time/,
  );
  assert.match(
    say({ totals: { ...partial, frames: 0 } }),
    /ended before a frame of the profile reached this server: .* The runtime addon switches the profiler off as the game quits, and did not here/,
  );
  assert.match(
    say({ totals: { ...partial, frames: 0 }, runtimeAddon: false, through: 'editor' }),
    /ended before a frame of the profile reached the editor.*This project has no gdharness runtime addon/,
  );
  assert.match(
    say({ totals: { ...totals({}), unreadable: 1 } }),
    /^1 message from the game could not be read/,
  );
  assert.match(
    say({ totals: { ...totals({}), unreadable: 2 } }),
    /^2 messages from the game could not be read/,
  );
  // A run still inside the frame its work is in, which has sent nothing and is not a profiler that
  // failed; and a run past it, whose frames are summed so far.
  assert.match(
    say({ running: true, totals: { ...partial, frames: 0 } }),
    /^The profiler is on and the game has not finished its first frame yet: .*the engine's own totals arrive when the game quits\.$/,
  );
  assert.match(say({ running: true, totals: { ...partial, frames: 1 } }), /one frame summed so far/);

  // What the cap leaves out, said for each way it can: some frames, every frame, the totals; and
  // nothing for a profile that never reached it or one read off a keeper older than the cap.
  const atCap = { ...partial, frameFunctions: 1536, cappedFrames: 1, totalCapped: false };
  assert.match(
    say({ running: true, totals: atCap }),
    /1 of the 3 frames carried the most functions the profiler asks for in one, 1536, so the functions with the least time in it are not counted there: 1536 is kept below the game's debugger queue \(network\/limits\/debugger\/max_queued_messages\)/,
  );
  assert.match(
    say({ running: true, totals: { ...atCap, cappedFrames: 3 } }),
    /All 3 frames carried .* in them/,
  );
  assert.match(say({ running: true, totals: { ...atCap, frames: 1 } }), /The one frame carried .* in it/);
  assert.match(
    say({ totals: { ...totals({}), frameFunctions: 1536, cappedFrames: 0, totalCapped: true } }),
    /^The engine's totals carried the most functions the profiler asks for, 1536, so the functions with the least time are not in them/,
  );
  // At the cap with the last function kept timed, something with time can be past it; with it untimed,
  // nothing past it took any. game-b's totals reached 1536 with 324 functions counted, the rest
  // compiled and never run, and the note said functions with time were missing.
  const atTheCap = (lastSeconds: number): ProfileTotals => ({
    ...totals({
      'res://crews.gd::4::Crews.busy': { calls: 10, selfSeconds: 0.4, totalSeconds: 0.4 },
      'res://crews.gd::9::Crews.idle': { calls: 0, selfSeconds: lastSeconds, totalSeconds: lastSeconds },
    }),
    frameFunctions: 1536,
    cappedFrames: 0,
    totalCapped: true,
  });
  assert.match(
    say({ totals: atTheCap(0.001) }),
    /1536, so the functions with the least time are not in them/,
  );
  assert.match(
    say({ totals: atTheCap(0) }),
    /^The engine's totals carried the most functions the profiler asks for, 1536, and the last of them took no measurable time, so neither did any left out: the time is all here/,
  );
  assert.equal(
    answer({ totals: { ...totals({}), frameFunctions: 1536, cappedFrames: 4, totalCapped: false } })['note'],
    undefined,
    'totals under the cap make the capped frames before them moot',
  );
  assert.doesNotMatch(say({ running: true, totals: { ...atCap, cappedFrames: 0 } }), /carried the most/);
  assert.doesNotMatch(say({ running: true, totals: { ...partial, cappedFrames: 2 } }), /carried the most/);
  assert.match(
    say({
      totals: totals({
        '#2155': { calls: 880, selfSeconds: 0.2, totalSeconds: 0.3 },
        '#2386': { calls: 60, selfSeconds: 0.01, totalSeconds: 0.01 },
        '#99': { calls: 0, selfSeconds: 9, totalSeconds: 9 },
        'res://a.gd::1::f': { calls: 1, selfSeconds: 0.1, totalSeconds: 0.1 },
      }),
    }),
    /^2 functions arrived without their names, shown as # and the number the engine gave them: .*They are script functions of the game/,
  );

  assert.equal(profileOnStart(false, 'gdharness', true), undefined, 'a start that did not ask says nothing');
  assert.match(
    String(profileOnStart(true, 'editor', true)?.totals),
    /^On from the game's start, through the editor's debugger session\. .*replace the sum when the game quits\.$/,
  );
  assert.match(
    String(profileOnStart(true, 'gdharness', false)?.totals),
    /through the process that keeps the run\. .*which takes the runtime addon: without it the frames that arrived before the exit are what is kept\.$/,
  );

  // Where a lambda is written and who names a function, off source shaped like a real project's: a
  // lambda whose body is on lines of its own, a string holding a line that begins with func, a
  // function written on one line, an inner class, and lambdas at a class's own level.
  const crewing = [
    'class_name Crewing',
    'extends Node',
    '',
    'var by_strength := func(a, b): return a < b',
    'var named := "_ranked_by"',
    '',
    '',
    'func _ranked_by(people: Array, key: Callable) -> Array:',
    '\tpeople.sort_custom(func(a, b): return key.call(a) > key.call(b))',
    '\treturn people',
    '',
    '',
    'func _brings_together(people: Array) -> Array:',
    '\tvar ranked := _ranked_by(people, _strength)',
    '\tfor one in ranked:',
    '\t\tvar note := """',
    'func fake():',
    '"""',
    '\t\tvar pick := func pick_one(x):',
    '',
    '\t\t\treturn _ranked_by([x], _strength)',
    '\t\tpick.call(one)',
    '\treturn ranked',
    '',
    '',
    'static func _crews_among(c: Crewing) -> Array: return c._ranked_by([], c._strength)',
    '',
    '',
    'func _strength(_one: Variant) -> int:',
    '\tvar later := _ranked_by  # _ranked_by( in a comment',
    '\treturn 0 if later else 1',
    '',
    '',
    'class Inner:',
    '\tfunc sort(xs: Array) -> void:',
    '\t\txs.sort_custom(func(a, b): return a < b)',
    '',
    '\tvar inner_lambda := func(): pass',
    '',
  ].join('\n');
  assert.deepEqual(
    [9, 14, 21, 26, 36, 4, 38, 99].map((line) => enclosingFunction(crewing, line)),
    ['_ranked_by', '_brings_together', '_brings_together', '_crews_among', 'sort', null, null, null],
    'each line in the named function written around it, and none for a line at a class level',
  );
  const other = [
    'class_name Other',
    '',
    'func _ranked_by(x: Array) -> Array:',
    '\treturn x',
    '',
    '',
    'func send_out(c: Crewing) -> void:',
    '\tc._ranked_by([], c._strength)',
    '',
    '',
    'func _brings_together() -> void:',
    '\t_ranked_by([])',
    '',
  ].join('\n');
  const crew = totals({
    'res://crewing.gd::9::Crewing._ranked_by': { calls: 716, selfSeconds: 0.9, totalSeconds: 1.8 },
    'res://crewing.gd::9::Crewing.<anonymous lambda>(lambda)': {
      calls: 16000,
      selfSeconds: 0.4,
      totalSeconds: 0.4,
    },
    'res://crewing.gd::14::Crewing._brings_together': { calls: 581, selfSeconds: 0.1, totalSeconds: 1.5 },
    'res://crewing.gd::26::Crewing._crews_among': { calls: 10, selfSeconds: 0.05, totalSeconds: 2 },
    'res://crewing.gd::21::Crewing.pick_one(lambda)': { calls: 581, selfSeconds: 0.02, totalSeconds: 0.5 },
    'res://other.gd::4::Other._ranked_by': { calls: 5, selfSeconds: 0.01, totalSeconds: 0.01 },
  });
  const sourceOf = (script: string): string | null => (script === 'res://crewing.gd' ? crewing : null);
  assert.deepEqual(
    profiledFunctions(crew, 10, sourceOf).functions.map((one) => [one.function, one.within]),
    [
      ['Crewing._ranked_by', undefined],
      ['Crewing.<anonymous lambda>(lambda)', '_ranked_by'],
      ['Crewing._brings_together', undefined],
      ['Crewing._crews_among', undefined],
      ['Crewing.pick_one(lambda)', '_brings_together'],
      ['Other._ranked_by', undefined],
    ],
    'the lambda placed in the function it is written in, and nothing added to a named function',
  );
  assert.equal(
    profiledFunctions(crew, 10).functions[1]?.within,
    undefined,
    'and a lambda whose script cannot be read is left as the engine named it',
  );
  const scripts = [
    ['res://crewing.gd', crewing],
    ['res://other.gd', other],
  ] as const;
  const found = callersOf(crew, '_ranked_by', scripts);
  assert.deepEqual(
    found.sites.map((one) => [
      one.script,
      one.line,
      one.within,
      one.called,
      one.withinCalls,
      one.withinTotalMs,
    ]),
    [
      ['res://crewing.gd', 26, '_crews_among', true, 10, 2000],
      ['res://crewing.gd', 14, '_brings_together', true, 581, 1500],
      ['res://crewing.gd', 21, '_brings_together', true, 581, 1500],
      ['res://crewing.gd', 30, '_strength', false, undefined, undefined],
      ['res://other.gd', 8, 'send_out', true, undefined, undefined],
      ['res://other.gd', 12, '_brings_together', true, undefined, undefined],
    ],
    'every place in code naming it, by the time of the function each is in; not its declarations, the string or the comment',
  );
  assert.deepEqual(
    [found.target.map((one) => one.function), found.omitted],
    [['Crewing._ranked_by', 'Other._ranked_by'], 0],
    "the rows of every function by that name, since a bare name does not say which class's",
  );
  assert.deepEqual(
    callersOf(crew, 'Crewing._ranked_by', scripts).target.map((one) => one.function),
    ['Crewing._ranked_by'],
    "and Class.name picks out the one class's",
  );
  const crowded = [
    'func many() -> void:',
    ...Array.from({ length: 41 }, () => '\t_ranked_by([], _strength)'),
  ].join('\n');
  const capped = callersOf(crew, '_ranked_by', [['res://many.gd', crowded]]);
  assert.deepEqual(
    [capped.sites.length, capped.omitted, capped.sites.at(-1)?.line],
    [40, 1, 41],
    'forty places and the count of the rest',
  );

  const withCallers = (name: string, from: readonly (readonly [string, string])[]): string =>
    String(get(answer({ totals: crew, callersOf: { name, scripts: () => from } }), 'callers', 'note'));
  assert.match(withCallers('_ranked_by', scripts), /^Found by name in the project's scripts/);
  assert.match(withCallers('_ranked_by', []), /^No script in the project names _ranked_by in code/);
  assert.match(
    withCallers('_strength', scripts),
    /The profile counts no call of _strength, so none of these places ran it while the profiler was on: withinCalls says the function a place is in ran, not that the line did\.$/,
  );
  // Places in functions that ran, and still no row: the line did not run, or the function fell past
  // the cap, or its name never arrived, each said only when this profile could have done it.
  // Reported from game-a: SkinImage.tinted, with callers at withinCalls 14 and 6.
  const noted = (shaped: Partial<ProfileTotals>): string =>
    String(
      get(
        answer({ totals: { ...crew, ...shaped }, callersOf: { name: '_strength', scripts: () => scripts } }),
        'callers',
        'note',
      ),
    );
  assert.match(
    noted({ complete: false, frameFunctions: 64, cappedFrames: 2 }),
    /The profile counts no call of _strength: either none of these places ran it while the profiler was on: withinCalls says the function a place is in ran, not that the line did, or its calls took too little time to be among the 64 functions a frame carried\.$/,
  );
  assert.match(
    noted({ frameFunctions: 64, totalCapped: true }),
    /, or its calls took too little time to be among the 64 functions the engine's totals carried\.$/,
  );
  assert.match(
    noted({ frameFunctions: 64, totalCapped: false, cappedFrames: 2 }),
    /, so none of these places ran it/,
    "the engine's totals stand in for the frames once they arrive, so only their cap counts",
  );
  const withUnnamed = (count: number): string =>
    noted({
      functions: {
        ...crew.functions,
        ...Object.fromEntries(
          Array.from({ length: count }, (_, index) => [
            `${UNNAMED_PREFIX}${index + 1}`,
            { calls: 3, selfSeconds: 0.001, totalSeconds: 0.001 },
          ]),
        ),
      },
    });
  assert.match(withUnnamed(1), /, or it is the function whose name never arrived\.$/);
  assert.match(withUnnamed(3), /, or it is one of the 3 functions whose name never arrived\.$/);
  assert.match(
    noted({
      complete: false,
      frameFunctions: 64,
      cappedFrames: 1,
      functions: { ...crew.functions, [`${UNNAMED_PREFIX}9`]: { calls: 1, selfSeconds: 0, totalSeconds: 0 } },
    }),
    /the line did, or its calls took too little time to be among the 64 functions a frame carried, or it is the function whose name never arrived\.$/,
  );

  // A property's get and set blocks, as the compiler names them, which no script calls by name: a
  // place naming the property runs them. Asked by either block's name or the property's, the rows
  // are both blocks' and the places are the property's. Reported from game-a and
  // game-b, whose tables named OutcomeReach.@sinks_setter and GameClock.@speed_getter.
  assert.deepEqual(
    [
      '@speed_getter',
      'GameClock.@speed_setter',
      'Reach.@sinks_and_hexes_getter',
      'speed',
      'Clock.@speed',
      'getter',
    ].map(propertyOf),
    ['speed', 'speed', 'sinks_and_hexes', null, null, null],
  );
  // The blocks name the property itself, as game-b's do: inside them that is the value stored,
  // which the engine reads and writes without running them, so those lines are not places. Each
  // place says whether it writes, which runs the set block, or reads. Reported from game-b as
  // #1020: every place read called: false, the setter's own `sinks = value` among them.
  const clock = [
    'class_name GameClock',
    '',
    'var speed: int = 1:',
    '\tget:',
    '\t\treturn speed',
    '\tset(value):',
    '\t\tspeed = value',
    '',
    '',
    'func tick() -> int:',
    '\tspeed += 1',
    '\treturn speed',
    '',
  ].join('\n');
  const hall = [
    'func open(clock: GameClock) -> void:',
    '\tclock.speed = 3',
    '\tprint(clock.speed == 3)',
    '',
  ].join('\n');
  const clocked = totals({
    'res://addons/gdharness_runtime/runtime_autoload.gd::310::_profiler_probe': {
      calls: 10_000,
      selfSeconds: 0.02,
      totalSeconds: 0.02,
    },
    'res://clock.gd::5::GameClock.@speed_getter': { calls: 40, selfSeconds: 0.001, totalSeconds: 0.001 },
    'res://clock.gd::7::GameClock.@speed_setter': { calls: 40_000, selfSeconds: 0.1, totalSeconds: 0.1 },
    'res://clock.gd::11::GameClock.tick': { calls: 40, selfSeconds: 0.2, totalSeconds: 0.3 },
  });
  assert.deepEqual(
    profiledFunctions(clocked, 10).functions.map((one) => [one.function, one.property, one.overheadMs]),
    [
      ['GameClock.tick', undefined, undefined],
      ['GameClock.@speed_setter', 'speed', 80],
      ['GameClock.@speed_getter', 'speed', undefined],
    ],
    'each block carries its property, and the setter is mostly the profiler',
  );
  const scriptsOfTheClock: [string, string][] = [
    ['res://clock.gd', clock],
    ['res://hall.gd', hall],
  ];
  for (const asked of ['GameClock.@speed_getter', 'GameClock.speed', '@speed_setter', 'speed']) {
    const found = callersOf(clocked, asked, scriptsOfTheClock);
    assert.deepEqual(
      [
        found.property,
        // The rows as the table has them, the profiler's share included: #1019 had it dropped here.
        found.target.map((one) => [one.function, one.overheadMs]),
        found.sites.map((one) => [one.script, one.line, one.within, one.access, one.called, one.withinCalls]),
      ],
      [
        true,
        [
          ['GameClock.@speed_setter', 80],
          ['GameClock.@speed_getter', undefined],
        ],
        [
          ['res://clock.gd', 11, 'tick', 'write', undefined, 40],
          ['res://clock.gd', 12, 'tick', 'read', undefined, 40],
          ['res://hall.gd', 2, 'open', 'write', undefined, undefined],
          ['res://hall.gd', 3, 'open', 'read', undefined, undefined],
        ],
      ],
      `asked as ${asked}`,
    );
  }
  assert.deepEqual(
    callersOf(clocked, 'Other.speed', scriptsOfTheClock).target,
    [],
    "another class's property of that name is not this one",
  );
  // Every compound assignment writes, and a comparison does not. Inside the block, the name on
  // another object is that object's property and runs its set block, so it is a place.
  const assigned = [
    'var level: int = 0:',
    '\tset(value):',
    '\t\tlevel = value',
    '\t\ttwin.level = value',
    'var twin: Node',
    '',
    '',
    'func shift() -> void:',
    ...['=', '+=', '-=', '*=', '/=', '%=', '**=', '<<=', '>>=', '&=', '|=', '^='].map(
      (op) => `\tlevel ${op} 2`,
    ),
    '\tprint(level == 2, level != 2, level <= 2, level >= 2)',
    '',
  ].join('\n');
  assert.deepEqual(
    callSitesOf(assigned, 'level', new Set(), true).map((one) => [one.line, one.access]),
    [
      [4, 'write'],
      ...Array.from({ length: 12 }, (_, index) => [index + 9, 'write']),
      [21, 'read'],
      [21, 'read'],
      [21, 'read'],
      [21, 'read'],
    ],
  );
  // And a function asked about is still called or passed on, with no access.
  assert.deepEqual(
    callSitesOf('func a() -> void:\n\tb()\n\tvar c := b\n\n\nfunc b() -> void:\n\tpass\n', 'b').map((one) => [
      one.line,
      one.called,
      one.access,
    ]),
    [
      [2, true, undefined],
      [3, false, undefined],
    ],
  );
  const noteFor = (name: string): string =>
    String(
      get(
        answer({ totals: clocked, callersOf: { name, scripts: () => scriptsOfTheClock } }),
        'callers',
        'note',
      ),
    );
  assert.match(
    noteFor('GameClock.speed'),
    / It is a property, so each place says whether it writes it \(access write\), which runs its set block, or reads it \(access read\), which runs its get block: .* so those lines are not listed\.$/,
  );
  assert.doesNotMatch(noteFor('tick'), /It is a property/, 'a function is not said to be one');

  // A super call is in its caller's self time as well as in the overridden function's row, so the
  // rows calling super are marked: each way of writing one, and the places that only look like one.
  const duel = [
    'class_name Run',
    'extends Pouched',
    '',
    '',
    'func _begin_duel(a: int) -> int:',
    '\tvar got := super(a)',
    '\treturn got',
    '',
    '',
    'func _begin_other() -> void:',
    '\tsuper._begin_duel(1)',
    '',
    '',
    'func one_line() -> int: return super.one_line() + 1',
    '',
    '',
    'func only_said() -> void:',
    '\tprint("super(a) in a string")  # super(a) in a comment',
    '',
    '',
    'func in_a_lambda() -> void:',
    '\tvar later := func(): return super.in_a_lambda()',
    '\tlater.call()',
    '',
    '',
    'func in_a_long_lambda() -> void:',
    '\tvar later := func():',
    '\t\tsuper.in_a_long_lambda()',
    '\tlater.call()',
    '',
    '',
    'func _supervise() -> void:',
    '\tsupervisor.super_x(my_super(1))',
    '',
  ].join('\n');
  const duelRows = (lines: readonly (readonly [number, string])[]): ProfileTotals =>
    totals(
      Object.fromEntries(
        lines.map(([line, name], at) => [
          `res://duel.gd::${line}::Run.${name}`,
          { calls: 1, selfSeconds: 0.1 * (lines.length - at), totalSeconds: 1 },
        ]),
      ),
    );
  const duels = duelRows([
    [6, '_begin_duel'],
    [11, '_begin_other'],
    [14, 'one_line'],
    [18, 'only_said'],
    [22, 'in_a_lambda'],
    [22, '<anonymous lambda>(lambda)'],
    [27, 'in_a_long_lambda'],
    [28, '<anonymous lambda>(lambda)'],
    [33, '_supervise'],
  ]);
  const duelSource = (script: string): string | null => (script === 'res://duel.gd' ? duel : null);
  assert.deepEqual(
    profiledFunctions(duels, 20, duelSource).functions.map((one) => [
      one.line,
      one.function,
      one.selfIncludesSuper,
    ]),
    [
      [6, 'Run._begin_duel', true],
      [11, 'Run._begin_other', true],
      [14, 'Run.one_line', true],
      [18, 'Run.only_said', undefined],
      [22, 'Run.in_a_lambda', undefined],
      [22, 'Run.<anonymous lambda>(lambda)', true],
      [27, 'Run.in_a_long_lambda', undefined],
      [28, 'Run.<anonymous lambda>(lambda)', true],
      [33, 'Run._supervise', undefined],
    ],
    'super( and super.name( in the body, on its header line or in a lambda; not in a comment, a string, a lambda written in the function, or a longer name holding super',
  );
  assert.match(
    String(answer({ totals: duels, sourceOf: duelSource })['note']),
    /^5 functions call through super, marked selfIncludesSuper: the engine takes every other call out of the caller's self time, and not a super call, so their selfMs holds the overridden function's time, which that function's own row counts again\. Self time therefore cannot be added along an override chain, and scriptMs counts the time under a super call once more for each level above it\.$/,
  );
  assert.match(
    String(answer({ totals: duelRows([[6, '_begin_duel']]), sourceOf: duelSource })['note']),
    /^One function calls through super, marked selfIncludesSuper: .* so its selfMs holds/,
  );
  assert.equal(
    answer({ totals: duels })['note'],
    undefined,
    'nothing is said of a source that cannot be read',
  );
  assert.deepEqual(
    callersOf(duels, '_begin_duel', [['res://duel.gd', duel]]).sites.map((one) => [
      one.line,
      one.within,
      one.withinSelfIncludesSuper,
    ]),
    [[11, '_begin_other', true]],
    'and a place in such a function says so beside its numbers',
  );

  // A name that is something else where it is written is not the function: a parameter, a local in
  // a block still open, a for variable, a match binding, a lambda's parameter, a class's own
  // variable. Reported from game-b as #989, where a helper's `lift: int` parameter was listed as
  // `lift` handed on as a Callable. And a call through another class the project declares is that
  // class's method when one class is asked about.
  const lifting = [
    'class_name Lifts',
    'extends RefCounted',
    '',
    '',
    'func placed(items: Array) -> int:',
    '\tvar lift: int = 0',
    '\tfor one in items:',
    '\t\tlift += one',
    '\treturn lift',
    '',
    '',
    'func handed() -> void:',
    '\tdone.connect(lift)',
    '',
    '',
    'func scoped(flag: bool) -> void:',
    '\tif flag:',
    '\t\tvar lift := 1',
    '\t\tprint(lift)',
    '\tlift()',
    '',
    '',
    'func looped() -> void:',
    '\tfor lift in range(3):',
    '\t\tprint(lift)',
    '',
    '',
    'func matched(x: Array) -> void:',
    '\tmatch x:',
    '\t\t[var lift, ..]:',
    '\t\t\tprint(lift)',
    '',
    '',
    'func lambdas() -> void:',
    '\tvar f := func(lift: int) -> int: return lift',
    '\tvar g := func(lift: int) -> int:',
    '\t\treturn lift',
    '\tf.call(g.call(1))',
    '',
    '',
    'func one_line(lift: int) -> int: return lift',
    '',
  ].join('\n');
  const kiln = [
    'extends Node',
    '',
    '',
    'func _bare(lift: int) -> void:',
    '\tvar made := Node.new()',
    '\tmade.bare_lift = lift',
    '',
  ].join('\n');
  const holding = [
    'class_name Holder',
    'extends Node',
    '',
    'var lift: int = 0',
    '',
    '',
    'func use() -> void:',
    '\tlift = 3',
    '',
  ].join('\n');
  const pouched = [
    'class_name Pouched',
    'extends Placed',
    '',
    '',
    'func go(loadout: Variant) -> void:',
    '\tApported.lift(loadout)',
    '\tPlaced.lift(loadout)',
    '\tself.lift(loadout)',
    '\tlift(loadout)',
    '',
  ].join('\n');
  const declaring = (name: string): string =>
    `class_name ${name}\n\n\nstatic func lift(x: Variant) -> void:\n\tprint(x)\n`;
  const project = [
    ['res://core/lifts.gd', lifting],
    ['res://tests/kiln_test.gd', kiln],
    ['res://core/holder.gd', holding],
    ['res://core/pouched.gd', pouched],
    ['res://core/apported.gd', declaring('Apported')],
    ['res://core/placed.gd', declaring('Placed')],
  ] as const;
  const placedAt = (name: string): unknown[] =>
    callersOf(totals({}), name, project).sites.map((one) => [one.script, one.line, one.called]);
  assert.deepEqual(
    placedAt('Placed.lift'),
    [
      ['res://core/lifts.gd', 13, false],
      ['res://core/lifts.gd', 20, true],
      ['res://core/pouched.gd', 7, true],
      ['res://core/pouched.gd', 8, true],
      ['res://core/pouched.gd', 9, true],
    ],
    'the Callable handed on and the calls, and none of the locals, the member variable or the call through Apported',
  );
  assert.deepEqual(
    placedAt('lift'),
    [
      ['res://core/lifts.gd', 13, false],
      ['res://core/lifts.gd', 20, true],
      ['res://core/pouched.gd', 6, true],
      ['res://core/pouched.gd', 7, true],
      ['res://core/pouched.gd', 8, true],
      ['res://core/pouched.gd', 9, true],
    ],
    'and with no class asked about, the call through another class is listed as the note says',
  );
  // A receiver declared as another class is that class's object, whichever way it was declared: a
  // typed local, a new(), a cast, a typed parameter, a typed for variable, a variable of the class.
  // Reported from game-b on 1.1.61, `made.lift(...)` with `var made: Outcome` above it. What says
  // nothing about the class stays: an untyped local, a receiver that is a member of something else,
  // and a variable declared as the class asked about.
  const paying = [
    'class_name Payout',
    'extends RefCounted',
    '',
    'var kept: Outcome = null',
    'var placed: Placed = null',
    '',
    '',
    'func pay(state: Variant, given: Outcome) -> void:',
    '\tvar made: Outcome = state.scratch',
    '\tmade.lift(1)',
    '\tvar built := Outcome.new()',
    '\tbuilt.lift(2)',
    '\tvar cast = state.other as Outcome',
    '\tcast.lift(3)',
    '\tgiven.lift(4)',
    '\tkept.lift(5)',
    '\tplaced.lift(6)',
    '\tstate.made.lift(7)',
    '\tvar loose = state.thing',
    '\tloose.lift(8)',
    '\tfor each: Outcome in []:',
    '\t\teach.lift(9)',
    '',
  ].join('\n');
  const paid = [
    ['res://core/payout.gd', paying],
    ['res://core/outcome.gd', declaring('Outcome')],
    ['res://core/placed.gd', declaring('Placed')],
  ] as const;
  const paidAt = (name: string): unknown[] =>
    callersOf(totals({}), name, paid)
      .sites.filter((one) => one.script === 'res://core/payout.gd')
      .map((one) => one.line);
  assert.deepEqual(
    paidAt('Placed.lift'),
    [17, 18, 20],
    'the receivers declared as Outcome are left out, and the Placed, dotted and untyped ones kept',
  );
  assert.deepEqual(
    paidAt('lift'),
    [10, 12, 14, 15, 16, 17, 18, 20, 22],
    'and asked by bare name, every one is listed',
  );

  // The profiler's own cost per call, read off the empty function the runtime addon calls as the
  // profiler goes on: it and its caller are the addon's, not the game's, so they are left out of the
  // rows, the count and scriptMs, and a row whose calls at that cost make up half its self time or
  // more says how much. Reported from game-a as #994. The note keeps two things
  // apart that a reader took for one: the overhead goes with the profiler whether or not a function
  // is inlined, and inlining removes only the call, which costs something unprofiled too.
  const calibrated = totals({
    'res://addons/gdharness_runtime/runtime_autoload.gd::310::_profiler_probe': {
      calls: 10_000,
      selfSeconds: 0.02,
      totalSeconds: 0.02,
    },
    'res://addons/gdharness_runtime/runtime_autoload.gd::300::_calibrate_the_profiler': {
      calls: 1,
      selfSeconds: 0.005,
      totalSeconds: 0.025,
    },
    'res://crews.gd::40::Crews.fits': { calls: 600_000, selfSeconds: 1.3, totalSeconds: 1.3 },
    'res://crews.gd::12::Crews.together': { calls: 10, selfSeconds: 0.5, totalSeconds: 1.8 },
  });
  const costed = profiledFunctions(calibrated, 10);
  assert.deepEqual(
    [costed.perCallUs, costed.counted, costed.scriptMs, costed.overheadDominated],
    [2, 2, 1800, 1],
    'two microseconds a call, and the two calibration rows counted nowhere',
  );
  assert.deepEqual(
    costed.functions.map((one) => [one.function, one.overheadMs]),
    [
      ['Crews.fits', 1200],
      ['Crews.together', undefined],
    ],
    'the hot predicate is mostly the profiler; the function doing the work is not',
  );
  const costNote = String(answer({ totals: calibrated })['note']);
  assert.match(
    costNote,
    /^The profiler costs about 2µs a call in this run, measured on an empty function the runtime addon calls as it goes on, .* One function has at least half its selfMs in it: Crews\.fits\. Its row carries that share as overheadMs\. That much of its time is the profiler's and goes once the profiler is off, whether the function is inlined or not\. What inlining saves is the call itself, .* not the work inside it\.$/,
    costNote,
  );
  assert.equal(get(answer({ totals: calibrated }), 'perCallOverheadUs'), 2);
  assert.equal(
    get(
      answer({
        totals: totals({
          'res://crews.gd::40::Crews.fits': { calls: 600_000, selfSeconds: 1.3, totalSeconds: 1.3 },
        }),
      }),
      'perCallOverheadUs',
    ),
    undefined,
    'and without the runtime addon there is no measurement to report',
  );
  // The runtime addon answering runtime_invoke inside the game: probe 60 found its argument check,
  // named _argument_count_refused, above the press it made, so a limit of one returned gdharness and
  // not the game. Summed apart, the rows, the count and scriptMs are the game's alone.
  const served = totals({
    'res://addons/gdharness_runtime/runtime_changes.gd::565::_argument_count_refused': {
      calls: 3,
      selfSeconds: 0.006,
      totalSeconds: 0.006,
    },
    'res://addons/gdharness_runtime/runtime_autoload.gd::120::_send_response': {
      calls: 3,
      selfSeconds: 0.001,
      totalSeconds: 0.001,
    },
    'res://main.gd::15::press': { calls: 3, selfSeconds: 0.003, totalSeconds: 0.0035 },
    'res://main.gd::11::step': { calls: 3, selfSeconds: 0.0005, totalSeconds: 0.0005 },
    // The loader setup writes outside addons/, compiling the runtime in its _ready: probe 198 found it
    // at the top of a profile at 779ms, read as the game's costliest function.
    'res://gdharness/loader.gd::27::_ready': { calls: 1, selfSeconds: 0.779, totalSeconds: 0.78 },
    // A script of the game's own beside the loader, which is not gdharness's for sharing its folder.
    'res://gdharness/loader_menu.gd::4::open': { calls: 1, selfSeconds: 0.0002, totalSeconds: 0.0002 },
  });
  const servedTable = profiledFunctions(served, 1);
  assert.deepEqual(
    [servedTable.functions.map((one) => one.function), servedTable.counted, servedTable.scriptMs],
    [['press'], 3, 3.7],
    "a limit of one returns the game's costliest function, and the runtime's rows count nowhere in the game's",
  );
  const servedAnswer = answer({ totals: served });
  assert.deepEqual(
    [get(servedAnswer, 'runtimeAddonMs'), get(servedAnswer, 'runtimeAddonFunctions')],
    [786, 3],
    'the addon and its loader are summed apart rather than dropped',
  );
  assert.match(
    String(servedAnswer['note']),
    /The gdharness runtime's own functions, its addon's and those of the loader that starts it, took 786ms of self time over 3 functions, starting the runtime as the game starts, answering tools such as runtime_invoke and sending the profile\. They are left out of functions, functionsCounted and scriptMs and summed under runtimeAddonMs/,
    `the note says where the addon's time went: ${String(servedAnswer['note'])}`,
  );
  assert.equal(
    get(answer({ totals: calibrated }), 'runtimeAddonMs'),
    undefined,
    'the calibration rows are the profiler measuring itself, not the addon serving a tool',
  );
  // Named in the note, since a limit can return none of them: two by name, and seven as the five with
  // the most self time and how many more. Reported from game-b: nine counted, none in the rows.
  const hot = (count: number): ProfileTotals =>
    totals({
      'res://addons/gdharness_runtime/runtime_autoload.gd::310::_profiler_probe': {
        calls: 10_000,
        selfSeconds: 0.02,
        totalSeconds: 0.02,
      },
      ...Object.fromEntries(
        Array.from({ length: count }, (_, index) => [
          `res://crews.gd::${index + 1}::Crews.hot${index}`,
          { calls: 100_000, selfSeconds: 0.2 + index * 0.01, totalSeconds: 0.2 + index * 0.01 },
        ]),
      ),
    });
  assert.match(
    String(answer({ totals: hot(2) })['note']),
    /2 functions have at least half their selfMs in it: Crews\.hot1 and Crews\.hot0\. Their rows carry that share as overheadMs\. That much of their time/,
  );
  assert.match(
    String(answer({ totals: hot(7) })['note']),
    /7 functions have at least half their selfMs in it: Crews\.hot6, Crews\.hot5, Crews\.hot4, Crews\.hot3, Crews\.hot2 and 2 more\. Their rows carry/,
  );
  // And where those rows are, since the field the note speaks of goes with any row a limit leaves
  // out. Reported from game-b as #1016: at limit 5 none of the 29 rows came back, and the note
  // pointed at overheadMs all the same. One function above them takes more time and is not mostly
  // the profiler's, so a limit can return none, some or all of them.
  const heavy = (count: number): ProfileTotals => ({
    ...hot(count),
    functions: {
      ...hot(count).functions,
      'res://crews.gd::90::Crews.heavy': { calls: 1, selfSeconds: 5, totalSeconds: 5 },
    },
  });
  const limited = (count: number, limit: number): string =>
    String(
      profileAnswer(
        { through: 'gdharness', running: false, totals: heavy(count), coveredMs: 0, runtimeAddon: true },
        limit,
      )['note'],
    );
  assert.match(
    limited(7, 1),
    /: Crews\.hot6, Crews\.hot5, Crews\.hot4, Crews\.hot3, Crews\.hot2 and 2 more\. Their rows, which carry that share as overheadMs, come after the one row returned; limit 8 returns them all\. That much/,
  );
  assert.match(
    limited(7, 3),
    / and 2 more\. Their rows carry that share as overheadMs, and 2 of them are among the 3 rows returned; limit 8 returns them all\. That much/,
  );
  assert.match(limited(7, 2), / and 1 of them is among the 2 rows returned; limit 8 returns them all\./);
  assert.match(limited(7, 8), / and 2 more\. Their rows carry that share as overheadMs\. That much/);
  assert.match(
    limited(1, 1),
    /One function has at least half its selfMs in it: Crews\.hot0\. Its row, which carries that share as overheadMs, comes after the one row returned; limit 2 returns it\. That much of its time/,
  );
  // One row returned and it one of several: game-b's limit 1 read "none of the 1 returned".
  assert.match(
    String(
      profileAnswer(
        { through: 'gdharness', running: false, totals: hot(7), coveredMs: 0, runtimeAddon: true },
        1,
      )['note'],
    ),
    / and 2 more\. Their rows carry that share as overheadMs, and the one row returned is one of them; limit 7 returns them all\./,
  );

  // Every thread's time is added to the same function, so script time beyond the time covered is
  // threads at work, which the note says, and with a super call marked, that the super call can be
  // some of it. Reported from game-a: a worker-thread function topped the table.
  const crewsWithSuper = [
    'class_name Crews',
    'extends Base',
    ...Array.from({ length: 8 }, () => ''),
    'func together() -> void:',
    '\tsuper()',
    '',
  ].join('\n');
  const threaded = (coveredMs: number, sourceOf?: SourceOf): string =>
    String(
      answer({ totals: calibrated, coveredMs, ...(sourceOf === undefined ? {} : { sourceOf }) })['note'],
    );
  assert.match(
    threaded(100),
    / scriptMs, 1800ms, is more than the 100ms the profile covers\. One thread cannot spend more time than passes, so that is functions running on several threads at once, through WorkerThreadPool or Thread\. The engine adds every thread's time to the same function and does not say which thread a call ran on, so a function's selfMs is summed over every thread it ran on rather than taken out of frames, and a function that waits for the others, through wait_for_group_task_completion or wait_to_finish, has the wait in its own selfMs as well\./,
  );
  assert.doesNotMatch(threaded(1800), /is more than the/, 'no more than the time covered is one thread');
  assert.match(threaded(1799), /scriptMs, 1800ms, is more than the 1799ms/);
  assert.match(
    threaded(100, (script) => (script === 'res://crews.gd' ? crewsWithSuper : null)),
    /is more than the 100ms the profile covers\. The super calls above, counted twice, can account for some or all of that; whatever they do not is functions running on several threads at once/,
  );

  // A script path comes from the game, so it is read only inside the project: a path climbing out of
  // it reads nothing, though the file it names is there, and nor does one built into a scene.
  const holder = mkdtempSync(join(tmpdir(), 'gdharness-sources-'));
  try {
    const inside = join(holder, 'project');
    mkdirSync(inside);
    writeFileSync(join(inside, 'crewing.gd'), crewing);
    writeFileSync(join(holder, 'outside.gd'), 'func outside() -> void:\n\tpass\n');
    const read = projectSourceOf(inside);
    assert.deepEqual(
      [
        read('res://crewing.gd') === crewing,
        read('res://../outside.gd'),
        read('res://crewing.tscn::GDScript_x'),
      ],
      [true, null, null],
      'the project script read, the one outside it and the built-in one not',
    );
  } finally {
    sweep(holder);
  }
}

async function turnedAwayAtTheBridge(
  bridge: ReturnType<typeof createBridge>,
  socket: (name: string) => FakeSocket,
  hello: (socket: FakeSocket, pid: number, opened?: boolean) => void,
  settled: () => Promise<void>,
  asked: number[],
  released: () => ((option: string | null) => void) | null,
): Promise<void> {
  // An import: turned away with its own code, and named.
  const importing = socket('import');
  connectFake(bridge, importing);
  hello(importing, 101);
  await settled();
  assert.equal(
    importing.closedWith?.code,
    4002,
    `an import is turned away: ${JSON.stringify(importing.closedWith)}`,
  );
  assert.match(importing.closedWith.reason, /pid 101 was started with --import/);
  assert.equal(bridge.getStatus().connected, false, 'and is not the editor');
  assert.equal(bridge.isArriving(), false, 'nor arriving, so nothing waits on it');
  assert.equal(bridge.getStatus().turnedAway?.pid, 101, 'and status names it');
  assert.equal(bridge.getStatus().turnedAway?.option, '--import');

  // The same process dialling in again is told at once, without another look at the machine.
  const again = socket('import again');
  connectFake(bridge, again);
  hello(again, 101);
  assert.equal(again.closedWith?.code, 4002, 'a known one-shot run is turned away at once');
  assert.deepEqual(asked, [101], 'without its command line being read again');

  // While the answer is coming the process is not counted, and once it says editor, it is. Before
  // its greeting and while it is looked up it is arriving, which is what a call waits out.
  const waiting = socket('waiting');
  connectFake(bridge, waiting);
  assert.equal(bridge.isArriving(), true, 'a socket that has not greeted is arriving');
  // Not connected yet either, or editor_status saw connected go true, false and true again as the
  // greeting started the lookup, and a fixture waiting on true met false on its next call.
  assert.deepEqual(
    [bridge.getStatus().connected, bridge.getStatus().identifying],
    [false, true],
    'and status reads it as being looked up, not connected',
  );
  hello(waiting, 104);
  await settled();
  assert.equal(bridge.getStatus().connected, false, 'not counted while it is being looked up');
  assert.equal(bridge.getStatus().identifying, true, 'and status says it is being looked up');
  assert.equal(bridge.isArriving(), true, 'and is still arriving');
  const release = released();
  assert.ok(release !== null, 'the reader was asked');
  release(null);
  await settled();
  assert.equal(bridge.getStatus().connected, true, 'an editor is served once its command line says so');
  assert.equal(bridge.getStatus().identifying, undefined);
  assert.equal(bridge.isArriving(), false, 'and has arrived');
  assert.equal(waiting.closedWith, null, 'and is not closed on the way');
  waiting.close();

  // A plain editor, and one whose command line could not be read, are served as before.
  for (const pid of [102, 103]) {
    const editor = socket(`editor ${pid}`);
    connectFake(bridge, editor);
    hello(editor, pid);
    await settled();
    assert.equal(bridge.getStatus().connected, true, `pid ${pid} is served`);
    editor.close();
  }

  // An editor a server opened is that server's, and is not looked up at all.
  const marked = socket('opened');
  connectFake(bridge, marked);
  hello(marked, 105, true);
  assert.equal(bridge.getStatus().connected, true, "a server's editor is served at once");
  assert.equal(asked.includes(105), false, 'without being looked up');
  marked.close();
}

function testSceneToolsVectorRegression(): void {
  const godotPath = resolveGodotPath();
  if (!godotPath) {
    // A skip is fine on a machine with no engine and never fine where the job exists to run
    // this: the engine job sets the flag so a missing install reads as a failure, not a pass.
    if (process.env['GDHARNESS_REQUIRE_GODOT']) {
      throw new Error('GDHARNESS_REQUIRE_GODOT is set and GODOT_PATH names no existing file.');
    }
    console.log('scene tools vector regression skipped (Godot not found)');
    return;
  }

  const projectDir = mkdtempSync(join(tmpdir(), 'gdharness-scene-vectors-'));
  try {
    mkdirSync(join(projectDir, 'scenes'), { recursive: true });
    // The whole addon rather than the tools file and a list of what it preloads. The list was
    // written by hand, so a helper added beside the others is one the fixture does not copy, and
    // what it fails on is a preload of a file that is not there rather than anything it tests.
    cpSync('src/godot/addons/gdharness_editor', join(projectDir, 'addons', 'gdharness_editor'), {
      recursive: true,
    });

    writeFileSync(
      join(projectDir, 'project.godot'),
      `; Engine configuration file.\n; It's best edited using the editor.\nconfig_version=5\n\n[application]\nconfig/name="SceneVectors"\n`,
    );

    writeFileSync(
      join(projectDir, 'runner.gd'),
      `extends SceneTree\n\nfunc _fail(message: String) -> void:\n\tprinterr(message)\n\tquit(1)\n\nfunc _init() -> void:\n\tvar root := Node2D.new()\n\troot.name = "Root"\n\tvar packed := PackedScene.new()\n\tif packed.pack(root) != OK:\n\t\t_fail("failed to pack root scene")\n\t\treturn\n\tif ResourceSaver.save(packed, "res://scenes/Test.tscn") != OK:\n\t\t_fail("failed to save root scene")\n\t\treturn\n\troot.queue_free()\n\n\tvar scene_tools = load("res://addons/gdharness_editor/tools/scene_tools.gd").new()\n\tvar project_path := ProjectSettings.globalize_path("res://")\n\n\tvar add_result: Dictionary = scene_tools.add_node({\n\t\t"projectPath": project_path,\n\t\t"scenePath": "res://scenes/Test.tscn",\n\t\t"nodeType": "Node2D",\n\t\t"nodeName": "TestNode",\n\t\t"parentNodePath": ".",\n\t\t"properties": {\n\t\t\t"position": {"x": 100, "y": 200},\n\t\t\t"scale": {"_type": "Vector2", "x": 2, "y": 2}\n\t\t}\n\t})\n\tif not add_result.get("ok", false):\n\t\t_fail("add_node failed: %s" % JSON.stringify(add_result))\n\t\treturn\n\n\tvar set_result: Dictionary = scene_tools.set_node_properties({\n\t\t"projectPath": project_path,\n\t\t"scenePath": "res://scenes/Test.tscn",\n\t\t"nodePath": "TestNode",\n\t\t"properties": {\n\t\t\t"position": [300, 400]\n\t\t}\n\t})\n\tif not set_result.get("ok", false):\n\t\t_fail("set_node_properties failed: %s" % JSON.stringify(set_result))\n\t\treturn\n\n\t# A tagged Resource class is built on the spot, which is how a region gets its polygon and a\n\t# tree its root without a wrapper tool per node class.\n\tvar nav_result: Dictionary = scene_tools.add_node({\n\t\t"projectPath": project_path,\n\t\t"scenePath": "res://scenes/Test.tscn",\n\t\t"nodeType": "NavigationRegion2D",\n\t\t"nodeName": "Walkable",\n\t\t"parentNodePath": ".",\n\t\t"properties": {"navigation_polygon": {"_type": "NavigationPolygon"}}\n\t})\n\tif not nav_result.get("ok", false):\n\t\t_fail("add_node NavigationRegion2D failed: %s" % JSON.stringify(nav_result))\n\t\treturn\n\tvar tree_result: Dictionary = scene_tools.add_node({\n\t\t"projectPath": project_path,\n\t\t"scenePath": "res://scenes/Test.tscn",\n\t\t"nodeType": "AnimationTree",\n\t\t"nodeName": "Tree",\n\t\t"parentNodePath": ".",\n\t\t"properties": {\n\t\t\t"anim_player": {"_type": "NodePath", "path": "../TestNode"},\n\t\t\t"tree_root": {"_type": "AnimationNodeStateMachine"}\n\t\t}\n\t})\n\tif not tree_result.get("ok", false):\n\t\t_fail("add_node AnimationTree failed: %s" % JSON.stringify(tree_result))\n\t\treturn\n\n\tvar loaded := load("res://scenes/Test.tscn") as PackedScene\n\tif loaded == null:\n\t\t_fail("failed to reload saved scene")\n\t\treturn\n\n\tvar instance := loaded.instantiate()\n\tvar node := instance.get_node_or_null("TestNode") as Node2D\n\tif node == null:\n\t\t_fail("saved node missing")\n\t\treturn\n\n\tif node.position != Vector2(300, 400):\n\t\t_fail("position mismatch: %s" % node.position)\n\t\treturn\n\tif node.scale != Vector2(2, 2):\n\t\t_fail("scale mismatch: %s" % node.scale)\n\t\treturn\n\tvar walkable := instance.get_node_or_null("Walkable") as NavigationRegion2D\n\tif walkable == null or walkable.navigation_polygon == null:\n\t\t_fail("the tagged NavigationPolygon should be built and saved")\n\t\treturn\n\tvar tree := instance.get_node_or_null("Tree") as AnimationTree\n\tif tree == null or not (tree.tree_root is AnimationNodeStateMachine) or tree.anim_player != NodePath("../TestNode"):\n\t\t_fail("the tagged AnimationNodeStateMachine and NodePath should be built and saved")\n\t\treturn\n\n\tprint(JSON.stringify({"ok": true, "position": [node.position.x, node.position.y], "scale": [node.scale.x, node.scale.y]}))\n\tinstance.queue_free()\n\tquit(0)\n`,
    );

    const run = spawnSyncHidden(
      godotPath,
      ['--headless', '--path', projectDir, '--script', join(projectDir, 'runner.gd')],
      {
        encoding: 'utf8',
        timeout: 120000,
      },
    );

    if (run.status !== 0) {
      throw new Error((run.stderr || run.stdout || `godot exited ${run.status}`).trim());
    }

    const output = `${run.stdout}\n${run.stderr}`;
    assert.match(output, /"ok"\s*:\s*true/, 'runner should report success JSON');
  } finally {
    sweep(projectDir);
  }
}

/** The port a listening server landed on, which `address()` only answers once it is up. */
function portOf(server: Server): number {
  const address = server.address();
  if (!address || typeof address === 'string') {
    throw new Error('The server is not listening on a TCP port.');
  }
  return address.port;
}

